export const faqData = [
	{
		question: "What kind of roles are you looking for?",
		answer:
			"Senior UI/UX Designer, Front-End Developer, or a combined design-and-build role where both sides of my experience get used. I am most at home on enterprise products, SaaS platforms and data-heavy applications — the places where good interface decisions matter most.",
	},
	{
		question: "Do you design as well as develop?",
		answer:
			"Yes, and that is the point. I design in Figma and Adobe XD, then build the same screens in HTML5, CSS3, SCSS, Bootstrap, JavaScript and React. Nothing is lost in handoff because there is no handoff — what gets designed is what gets shipped.",
	},
	{
		question: "Are you open to remote or relocation?",
		answer:
			"I am based in Hyderabad and open to on-site, hybrid and remote roles. For the right opportunity I am happy to discuss relocation — get in touch and we can talk it through.",
	},
	{
		question: "How do you use AI in your process?",
		answer:
			"For research synthesis, layout exploration, component scaffolding and boilerplate — the parts that used to eat the schedule. Every output still goes through the same review for accessibility, performance and brand consistency. AI shortens the path to a decision; it does not make the decision.",
	},
	{
		question: "Is your work responsive and accessible?",
		answer:
			"Always. Every build is tested across desktop, tablet and mobile with cross-browser compatibility, semantic HTML, sensible colour contrast and keyboard-navigable components as the baseline rather than an afterthought.",
	},
	{
		question: "What is the best way to reach you?",
		answer:
			"Use the contact form, or email me directly — both reach me quickly. If you would like my full CV or references, just ask and I will send them across.",
	},
];
